tool_input.command:
node --test test/ 2>&1 | tail -12
mkdir -p /tmp/remflow && cat > /tmp/remflow/probe.mjs <<'EOF'
const root = process.argv[2];
const { handle } = await import(`${root}/src/api.js`);
const { tick } = await import(`${root}/src/scheduler.js`);
const { reset } = await import(`${root}/src/db.js`);
for (const [label, off] of [['UTC', 0], ['IST', 330], ['EST', -300]]) {
  reset();
  const { body } = handle({ method: 'POST', path: '/reminders', body: { userId: 'u1', text: 'call mum', at: '2026-03-01T09:00', tzOffsetMin: off } });
  const correct = body.due_ms;
  let firedAt = null;
  for (let t = correct - 8 * 3600e3; t <= correct + 8 * 3600e3 && firedAt === null; t += 60e3) {
    await tick(t, { out: () => { firedAt = t; } });
  }
  console.log(label, 'correct UTC', new Date(correct).toISOString(), '| fired at', new Date(firedAt).toISOString(), '| off by', (firedAt - correct) / 3600e3, 'h');
}
EOF
node /tmp/remflow/probe.mjs "$PWD" 2>&1 | grep -v '^REMIND'

